import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO quote — base premiums and fee", () => {
  it.todo("empty item list → premium 5 G (only the processing fee)");
  it.todo("single sword (no modifiers, 0 years, first contract) → 100 base + 10 first insurance + 5 fee = 115 G");
  it.todo("single amulet base premium 60 → 60 + 10 first + 5 fee = 75 G");
  it.todo("single staff base premium 80 → 80 + 10 first + 5 fee = 95 G");
  it.todo("single potion base premium 40 → 40 + 10 first + 5 fee = 55 G");
});

describe("MHPCO quote — components and blocks", () => {
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
});

describe("MHPCO quote — item modifiers", () => {
  it.todo("cursed sword (enchantment 3) adds 50% of item base premium (50 G surcharge)");
  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies (30 G)");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 → both surcharges apply");
});

describe("MHPCO quote — policy-wide modifiers", () => {
  it.todo("customer with exactly 2 years → 20% loyalty discount on policy base");
  it.todo("cursed sword + plain amulet → base 160 G; curse surcharge 50 G (on cursed item base) → 210 G before fee");
  it.todo("each item in a quote is treated as first insurance regardless of customer history");
  it.todo("second quote in scenario receives 15% follow-up contract discount");
});

describe("MHPCO quote — rounding", () => {
  it.todo("premium yielding 197.5 G → final premium 198 G (rounded up)");
});

describe("MHPCO quote — integration examples", () => {
  it.todo("newcomer with cursed sword (steel, ench 3), 0 years → premium 165 G");
  it.todo("long-standing customer's second contract: cursed sword (steel, ench 7), 3 years → premium 160 G");
});

describe("MHPCO quote — errors", () => {
  it.todo("quote with unknown item type (e.g. broomstick) → runScenario throws an error (CLI exits non-zero, stderr message, no results)");
});

describe("MHPCO claim — standard reimbursement", () => {
  it.todo("regular sword (steel, ench 3), damage 500 → payout 400 (full minus 100 deductible)");
  it.todo("rune (value 250), damage 200 → payout 100 (full minus 100 deductible; no special clause)");
});

describe("MHPCO claim — special clauses", () => {
  it.todo("dragon-material sword, ench 5, damage 800 → payout 700 (full reimbursement, then deductible)");
  it.todo("steel sword, ench 9, damage 1000 → payout 400 (50% first, then deductible: 500 − 100)");
  it.todo("dragon-material sword, ench 8, damage 1000 → payout 400 (high-enchantment 50% wins, then deductible)");
  it.todo("dragon-material sword, ench 9, damage 1000 → payout 400 (both clauses, 50% wins, then deductible)");
});

describe("MHPCO claim — deductible per damage event", () => {
  it.todo("dragon attack damages sword (500) and amulet (300) → payout 600 (deductible once per damaged item)");
});

describe("MHPCO claim — cap", () => {
  it.todo("policy sword+amulet → insurance sum 1600, cap 3200");
  it.todo("cursed sword → cap 2000 (based on unmodified insurance value)");
  it.todo("sword + 3 runes block → insurance sum 1750 (block discount does not affect insurance sum)");
  it.todo("sword (cap 2000), first claim 1500 → payout 1400, remainingCap 600");
  it.todo("sword (cap 2000), second claim 1500 → payout 600, remainingCap 0 (reduced to remaining cap)");
});

describe("MHPCO claim — multiple items of same type", () => {
  it.todo("two swords insured → insurance sum 2000, cap 4000; both damaged → each own deductible");
  it.todo("more damages of a type than insured (two sword damages, one sword) → runScenario throws (CLI non-zero)");
});

describe("MHPCO claim — rounding", () => {
  it.todo("payout yielding 350.5 G → final payout 350 G (rounded down)");
});

describe("MHPCO claim — errors", () => {
  it.todo("damage entry item not in policy (amulet when only sword insured) → runScenario throws (CLI non-zero, stderr)");
  it.todo("damage entry with negative amount (-200) → runScenario throws (CLI non-zero, stderr)");
});

describe("MHPCO scenario integration (schema example)", () => {
  it.todo("amulet quote then amulet claim (damage 200) → results [{premium}, {payout,remainingCap}]");
});

