const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;
const CURSE_SURCHARGE = 0.5;
const ROUNDING_EPSILON = 1e-9;

function roundPremium(amount: number): number {
  return Math.ceil(amount - ROUNDING_EPSILON);
}

const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

const MAIN_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

function isComponent(type: string): boolean {
  return COMPONENT_TYPES.has(type);
}

function componentGroupPremium(count: number): number {
  if (count === BLOCK_SIZE) {
    return BLOCK_BASE_PREMIUM;
  }
  return count * COMPONENT_BASE_PREMIUM;
}

export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export type Step = QuoteStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioResult {
  results: QuoteResult[];
}

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
}

function policyBasePremium(items: Item[]): number {
  let total = 0;
  for (const [type, count] of countByType(items)) {
    total += isComponent(type)
      ? componentGroupPremium(count)
      : MAIN_BASE_PREMIUMS[type] * count;
  }
  return total;
}

function computeQuote(step: QuoteStep): QuoteResult {
  const policyBase = policyBasePremium(step.items);
  const withFirstInsurance = policyBase * (1 + FIRST_INSURANCE_SURCHARGE);
  const premium = roundPremium(withFirstInsurance + PROCESSING_FEE);
  return { premium };
}

export function runScenario(scenario: Scenario): ScenarioResult {
  const results = scenario.steps.map((step) => computeQuote(step));
  return { results };
}

